from datetime import date
from decimal import Decimal, ROUND_HALF_UP
from .modeller import Odunc

# Ödünç sınırı: üye türüne göre
_MAX_ODUNC = {"standart": 3, "ogrenci": 5}


def _ceza_hesapla(alinma: date, iade: date, uye_turu: str) -> float:
    """İade cezasını hesapla ve 2 ondalığa yuvarla."""
    gecikme_gun = (iade - alinma).days - 14
    if gecikme_gun <= 0:
        return 0.0

    # İlk 7 gün: 2,50 TL/gün, sonraki günler: 5,00 TL/gün, max 150 TL
    if gecikme_gun <= 7:
        ceza = gecikme_gun * 2.50
    else:
        ceza = 7 * 2.50 + (gecikme_gun - 7) * 5.00

    if ceza > 150.0:
        ceza = 150.0

    # Öğrenci %50 indirim
    if uye_turu == "ogrenci":
        ceza *= 0.50

    # 2 ondalığa yuvarlama (Decimal kullanarak yuvarlama hatasını önle)
    ceza = Decimal(str(ceza)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return float(ceza)


class KutuphaneServisi:
    def __init__(self):
        self.kitaplar = {}
        self.uyeler = {}
        self.kayitlar = []

    def kitap_ekle(self, kitap):
        self.kitaplar[kitap.id] = kitap

    def uye_ekle(self, uye):
        self.uyeler[uye.id] = uye

    def _aktif(self, kitap_id):
        return next((k for k in self.kayitlar if k.kitap_id == kitap_id and k.iade is None), None)

    def odunc_ver(self, kitap_id, uye_id, tarih):
        """Kitabı üyeye verir. Kitap/üye yoksa ya da kitap zaten ödünçteyse ValueError."""
        if kitap_id not in self.kitaplar or uye_id not in self.uyeler:
            raise ValueError("kitap ya da üye bulunamadı")
        if self._aktif(kitap_id):
            raise ValueError("kitap zaten ödünçte")

        # Ödünç sınırı kontrolü
        uye = self.uyeler[uye_id]
        aktif_sayisi = sum(
            1 for k in self.kayitlar if k.uye_id == uye_id and k.iade is None
        )
        max_odunc = _MAX_ODUNC.get(uye.tur, _MAX_ODUNC["standart"])
        if aktif_sayisi >= max_odunc:
            raise ValueError(
                f"üye limiti aşıldı (mizin {aktif_sayisi}/{max_odunc} kitap)"
            )

        kayit = Odunc(kitap_id, uye_id, tarih)
        self.kayitlar.append(kayit)
        return kayit

    def iade_al(self, kitap_id, tarih):
        """Kitabın iadesini alır ve ödünç kaydını döndürür (ceza hesaplanmış).
        Kitap ödünçte değilse ValueError."""
        kayit = self._aktif(kitap_id)
        if kayit is None:
            raise ValueError("kitap ödünçte değil")

        uye = self.uyeler[kayit.uye_id]
        kayit.ceza = _ceza_hesapla(kayit.alinma, tarih, uye.tur)
        kayit.iade = tarih
        return kayit

    def oduncteki_kitaplar(self, uye_id):
        return sorted(k.kitap_id for k in self.kayitlar if k.uye_id == uye_id and k.iade is None)

    def toplam_ceza(self, uye_id):
        """Üyenin iade edilmiş tüm ödünçlerinin cezaları toplamı."""
        return sum(
            k.ceza for k in self.kayitlar
            if k.uye_id == uye_id and k.iade is not None
        )
